#!/usr/bin/env python3
"""Freeze a new metadata namespace; never builds, stages or launches anything."""
import argparse,hashlib,json,shutil
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 a=argparse.ArgumentParser(description=__doc__);a.add_argument('--plan',type=Path,required=True);a=a.parse_args();d=a.plan/'observer-runtime-04';here=Path(__file__).parent
 if (d/'binding.json').exists():raise SystemExit('preserve existing binding; use explicit new namespace revision')
 binding=json.loads((a.plan/'observer-runtime-03/binding.json').read_text());binding.update(namespace='observer-runtime-04',phase_audit='phase-contract.json',path_audit='runtime04-path-width-report.json',inputs_sha256=sha(a.plan/'inputs-final/plan-inputs.json'),scope='OFFLINE QUALIFIED SOURCE ONLY. No target guest allocated. Completed-phase coverage must be measured before any paired comparison.')
 shutil.copyfile(a.plan/'observer-runtime-03/scene-existing-dwarf02.json',d/'scene-existing-dwarf02.json')
 criteria={'result':'PLANNED_NOT_RUNTIME_ACCEPTED','source_window':{'coverage_only_first':240,'coverage_only_last':360,'comparison_if_future_all_gates_pass':[241,360],'predecessor':240,'no_sliding_or_selection_or_tolerance':True},'identity':'Exact a585 programme/e08c ELF/all14 overlays/actual preprocessing, immutable observer/source/binding/controller; fresh same-program cold lineage and exact staged asset identities required','phase':'Pre/post identical nonzero even current completed sequence; completed native frame/present/abort; sourceFrame==UIFrame+actual pace_skipped_frames modulo32; Rno0=3+ordinary flags; current SndWatcher/PROCESS CPU cursor+positive CPU ticks; same zeroTick+all source pointers; stable reread of every body dependency','coverage':'Every requested frame 240..360 has at least one qualified completed observation and zero differing accepted variants. Keep all variants/rejections. Any missing/conflicting frame blocks pair. Table channel separately latched and cannot replace scene samples. No SQ-witness sampling in this channel because direct_open must0.','paired_scene':'Exact player/active-camera/controller-camera/health/room/ordinary controls and phase/source-frame/counter semantics across arms. Source pose equality is not presentation identity. Render uses previous source state: retain 240 predecessor and trace presentation binding before timing acceptance.','behavioral_control':'BLOCKED for current C assets: remapped R4PW body CRC versus stale R4TC expected CRC falls back classes=other; stale R4ID header CRC yields ids=header placements=0. Frozen TRANS_POLICY3/DYNAMIC1 behavior differs. Rectangle owns CRC-consumer repair qualification. No B/C comparison until all source behavior/placement/class/material controls are proved equivalent against repaired frozen assets. No asset changes by this tool.','memory':'Typed selected key descriptors/CRC/live owned pointers and minimum known allocation only; not full allocator high water/net VRAM or all-key vertices/raster','timing':'Direct total/exclusive host Flycast CPU semantics only after all gates. Never add overlapping rows. No physical Dreamcast ms/FPS or performance-improvement acceptance. Historical A and strict47/120 failed B01/C03 remain separate.','allocation':'No new image/programme/guest/replay/state writes. Future coverage guest needs root allocation; rectangle owns runtime and global resource bounds.'}
 (d/'coverage-contract.json').write_text(json.dumps(criteria,indent=2)+'\n')
 sources=('observer.py','phase_latch.py','phase_latch04.py','observer04.py')
 binding['source_sha256']={name:sha(here/name) for name in sources}
 assert binding['source_sha256']['observer.py']=='694b31d3442beb135638dfbb88ebef7923a7616ee0faf5ca23feba9cd13d35b3'
 assert binding['source_sha256']['phase_latch.py']=='8deb19b1f465d9ff0b940def14bf6c2b93c27c8dd486980d7cd0486ce48c5436'
 for name in sources:shutil.copyfile(here/name,d/name)
 binding['metadata_sha256']={name:sha(d/name) for name in ('scene-existing-dwarf02.json','scene-package-paths.json','phase-contract.json','runtime04-path-width-report.json','coverage-contract.json')}
 (d/'binding.json').write_text(json.dumps(binding,indent=2)+'\n');print(json.dumps({'observer04_sha256':binding['source_sha256']['observer04.py'],'phase04_sha256':binding['source_sha256']['phase_latch04.py'],'binding_sha256':sha(d/'binding.json')}))
if __name__=='__main__':main()
